import json
from fractions import Fraction
from math import isqrt

# Polynomials in the independent variables x, t, c.
ZERO = (0, 0, 0)

def constant(value):
    value = Fraction(value)
    return {ZERO: value} if value else {}

def add(*polynomials):
    result = {}
    for polynomial in polynomials:
        for powers, coefficient in polynomial.items():
            result[powers] = result.get(powers, Fraction(0)) + coefficient
    return {p: a for p, a in result.items() if a}

def scale(polynomial, factor):
    return {p: a * factor for p, a in polynomial.items() if a * factor}

def multiply(left, right):
    result = {}
    for p, a in left.items():
        for q, b in right.items():
            powers = tuple(u + v for u, v in zip(p, q))
            result[powers] = result.get(powers, Fraction(0)) + a * b
    return {p: a for p, a in result.items() if a}

def substitute_c(polynomial, value):
    result = {}
    for (px, pt, pc), coefficient in polynomial.items():
        powers = (px, pt)
        result[powers] = result.get(powers, Fraction(0)) + coefficient * value**pc
    return {p: a for p, a in result.items() if a}

def unsupported():
    print("UNSUPPORTED")
    raise SystemExit

x = {(1, 0, 0): Fraction(1)}
t = {(0, 1, 0): Fraction(1)}
c = {(0, 0, 1): Fraction(1)}

def f(argument):
    return add(constant(1), multiply(c, argument))

# Put t = x+y. Since y is arbitrary, x and t range independently
# over all reals. The original identity becomes
# f(x)f(t) = f(x+t) - x f(t) + x.
residual = add(
    multiply(f(x), f(t)),
    scale(f(add(x, t)), -1),
    multiply(x, f(t)),
    scale(x, -1),
)

# The symmetry argument in the evidence forces f(t)=1+c*t.
# Extract the resulting exact constraint on c.
if any((px, pt) != (1, 1) for px, pt, pc in residual):
    unsupported()

coefficients = {
    pc: coefficient for (px, pt, pc), coefficient in residual.items()
}
if any(power > 2 for power in coefficients):
    unsupported()

a = coefficients.get(2, Fraction(0))
b = coefficients.get(1, Fraction(0))
d = coefficients.get(0, Fraction(0))
if not a:
    unsupported()

discriminant = b*b - 4*a*d
if discriminant < 0:
    unsupported()

numerator_root = isqrt(discriminant.numerator)
denominator_root = isqrt(discriminant.denominator)
if (numerator_root**2 != discriminant.numerator or
        denominator_root**2 != discriminant.denominator):
    unsupported()

sqrt_discriminant = Fraction(numerator_root, denominator_root)
roots = sorted({
    (-b - sqrt_discriminant) / (2*a),
    (-b + sqrt_discriminant) / (2*a),
})
valid = [
    slope for slope in roots
    if slope != 0 and not substitute_c(residual, slope)
]
if len(valid) != 1:
    unsupported()

slope = valid[0]
magnitude = abs(slope)
term = "x" if magnitude == 1 else f"({magnitude})*x"
formula = f"f(x) = 1 {'+' if slope > 0 else '-'} {term} for every real x."

print(json.dumps({
    "final_answer": formula,
    "evidence": {
        "domain_reduction": "Set t=x+y; x and t are arbitrary real numbers.",
        "f_at_zero": (
            "At x=0, (f(0)-1)f(t)=0 for every t. Injectivity "
            "prevents f from being identically zero, so f(0)=1."
        ),
        "forced_form": (
            "Swapping x and t gives x(f(t)-1)=t(f(x)-1). "
            "Taking x=1 forces f(t)=1+c*t, where c=f(1)-1."
        ),
        "constraint_coefficients_c2_c_1": [str(a), str(b), str(d)],
        "all_constraint_roots": [str(root) for root in roots],
        "injectivity_condition": "c != 0",
        "selected_slope": str(slope),
        "original_identity_residual": (
            "The substituted polynomial is identically zero; "
            "the nonzero slope also proves injectivity."
        )
    }
}, separators=(",", ":")))
